// Restore the exact approved binary assets during the Cloudflare Pages build.
const fs = require("node:fs");
const assets = {"favicon.ico": "", "favicon-48.png": "", "favicon-512.png": "", "apple-touch-icon.png": "", "og-cover.jpg": ""};
for (const [name, data] of Object.entries(assets)) fs.writeFileSync(name, Buffer.from(data, "base64"));
console.log("Restored " + Object.keys(assets).length + " approved SOLUCIONAMOS assets.");
